/* Source-scoped bridge lessons, independently authored for beginner skills omitted from earlier chapter flow. Teacher review pending. */
(()=>{'use strict';
const chapters=[{"n":2,"title":"Before your Chapter 2 activities","blocks":[{"key":"numbers","title":"Numbers beyond 20","purpose":"Read ages, work hours, quantities and everyday profile numbers.","text":"You already learned one through twenty. German now builds many larger numbers by putting the ones first and the tens last. Twenty-one is einundzwanzig: literally one-and-twenty. Notice that eins becomes ein inside the compound. Thirty is dreißig, forty is vierzig, sixty is sechzig and seventy is siebzig. Say each compound as one word. In a profile you might see 24 years old, a starting time or a phone number. Recognising larger numbers lets you understand these details before answering questions about them.","examples":[["21 = einundzwanzig","one-and-twenty"],["32 = zweiunddreißig","two-and-thirty"],["47 = siebenundvierzig","seven-and-forty"],["80 = achtzig · 100 = hundert","eighty; one hundred"]],"note":"The tens are zwanzig (20), dreißig (30), vierzig (40), fünfzig (50), sechzig (60), siebzig (70), achtzig (80), neunzig (90), hundert (100).","task":"Say 26, 41 and 73 in German before continuing.","answer":"sechsundzwanzig · einundvierzig · dreiundsiebzig"},{"key":"calendar","title":"All weekdays and months","purpose":"Read a date and propose a day rather than guessing it.","text":"For meetings, you need more than Freitag and Samstag. The seven weekdays are Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag and Sonntag. The twelve months are Januar, Februar, März, April, Mai, Juni, Juli, August, September, Oktober, November and Dezember. German capitalises these names. Say am Mittwoch when planning a weekday, and im Sommer when talking about a season. A calendar gives context: it lets you check whether a suggested day is available, choose another, and read a work or leisure profile. You will practise full dates with endings in Chapter 6.","examples":[["Hast du am Mittwoch Zeit?","Are you free on Wednesday?"],["Im Dezember arbeite ich.","I work in December."],["Im Frühling schwimme ich gern.","I enjoy swimming in spring."]],"note":"Weekdays take am. Months can take im when referring generally to the month. Full dates with ordinal endings are introduced later.","task":"Name the weekday after Dienstag and the month after August.","answer":"Mittwoch · September"},{"key":"conjugation","title":"Build statements and yes/no questions","purpose":"Use haben, sein and everyday hobby verbs before responding to questions.","text":"German verb endings change with the person. Learn complete examples: ich bin, du bist, er/sie ist; ich habe, du hast, er/sie hat. For regular verbs, ich spiele, du spielst, er/sie spielt. A normal statement places the conjugated verb in second position: Am Samstag habe ich Zeit. A yes/no question begins with the verb: Hast du am Samstag Zeit? When asking about hobbies, put gern after the action verb: Ich lese gern. Listening matters too: your voice normally falls at the end of a statement, while a yes/no question may sound inviting or questioning.","examples":[["Ich bin Studentin. Du bist Student.","I am a student. You are a student."],["Ich habe Zeit. Hast du Zeit?","I have time. Do you have time?"],["Sie spielt gern Tennis.","She enjoys playing tennis."]],"note":"In informal speech, du uses bist/hast/spielst. Polite Sie uses sind/haben/spielen; don't mix those forms.","task":"Make a question out of Du hast am Freitag Zeit.","answer":"Hast du am Freitag Zeit?"}]},{"n":3,"title":"Before your Chapter 3 activities","blocks":[{"key":"articles","title":"Name, introduce and negate a place","purpose":"Understand der/ein/kein and die/eine/keine before city-map choices.","text":"The articles in a city map depend on the noun. Bahnhof is masculine: der Bahnhof, ein Bahnhof, kein Bahnhof. Bank is feminine: die Bank, eine Bank, keine Bank. Museum is neuter: das Museum, ein Museum, kein Museum. Use the indefinite article when introducing an unfamiliar place and a definite article after the place has been identified. To say no such place is present, use kein/keine rather than simply saying nein plus the noun. These examples use simple nominative sentences with ist. The accusative after other verbs is introduced in Chapter 4.","examples":[["Das ist ein Bahnhof.","That is a station."],["Der Bahnhof ist groß.","The station is big."],["Hier ist kein Bahnhof.","There is no station here."],["Hier ist keine Bank.","There is no bank here."]],"note":"Learn the noun with its article, not as an isolated English translation. A complete negative sentence needs the verb.","task":"Say 'There is no museum here' using ist.","answer":"Hier ist kein Museum."},{"key":"map","title":"A city map and ordered directions","purpose":"Practise routes before you are asked to guide somebody.","text":"A direction task needs a starting point and a destination. Imagine the station on a straight street, a crossing ahead, and the museum on the street to the left. First say Entschuldigung, wo ist das Museum? Then describe the route: Gehen Sie geradeaus. Dann biegen Sie links ab. The finite verb comes first in this polite Sie instruction, followed by Sie. Links means left, rechts right and geradeaus straight ahead. Listen for then/next words because changing one step can change the destination. After practising, check a route against the accompanying city illustration.","examples":[["Wo ist der Bahnhof?","Where is the station?"],["Gehen Sie bitte geradeaus.","Please go straight ahead."],["Dann biegen Sie links ab.","Then turn left."],["Vielen Dank!","Thank you very much!"]],"note":"When you give directions to a stranger, use Gehen Sie / Biegen Sie, not an informal du question.","task":"Say two polite instructions: go straight, then turn right.","answer":"Gehen Sie geradeaus. Dann biegen Sie rechts ab."},{"key":"vowels","title":"Long and short German vowels","purpose":"Hear place names and short route messages more clearly.","text":"German distinguishes vowel length. In Stadt, the a is short; in Straße, the a is long. In bitte, the i is short; in sieben, the ie is pronounced as a long i sound. Listen to the complete word before repeating it. A longer vowel is not simply a louder vowel. This helps when you hear a place name on a route. Read a short, original notice such as 'Bus zum Museum. Samstag, zehn Uhr.' Ask which transport, destination and day it names. You should be able to find these facts without having to know every German sign in a town.","examples":[["die Stadt","the city; short a"],["die Straße","the street; long a"],["bitte","please; short i"],["sieben","seven; long ie"]],"note":"Pronunciation cues are approximations; use the German speech playback and compare short versus long vowels.","task":"Which word has a long i sound: bitte or sieben?","answer":"sieben"}]},{"n":4,"title":"Before your Chapter 4 activities","blocks":[{"key":"quantities","title":"Food quantities and prices","purpose":"Make a shopping list and read prices without guessing what to buy.","text":"Shop talk needs quantities. Say zwei Tomaten when buying countable tomatoes, ein Kilo Äpfel for a kilogram of apples, eine Packung Milch for a carton of milk, and ein Stück Käse for a piece of cheese. The quantity word is part of the request, so read it alongside the food. German shop prices use Euro and Cent: drei Euro fünfzig means €3.50. A short shopping note can tell you which item, how much, and where to buy it. Ask Was kostet das? for the price of an item, or Was kostet das zusammen? for the combined total.","examples":[["Zwei Tomaten, bitte.","Two tomatoes, please."],["Ein Kilo Äpfel, bitte.","One kilogram of apples, please."],["Eine Packung Milch, bitte.","One carton of milk, please."],["Das kostet drei Euro fünfzig.","That costs €3.50."]],"note":"Brötchen is a bread roll, not a sandwich. Bäckerei names the shop where bread products are sold.","task":"Ask politely for one carton of milk.","answer":"Eine Packung Milch, bitte."},{"key":"accusative","title":"The accusative you need for shopping","purpose":"Understand the article change before buying, ordering and checking grammar.","text":"A direct object tells you what somebody buys or wants. In Der Apfel ist rot, Apfel is the subject and uses der. In Ich kaufe den Apfel, it is the object, so der becomes den. In a similar sentence, ein becomes einen: Ich kaufe einen Apfel. Feminine die/eine and neuter das/ein do not change in these simple accusative examples. Identify the noun's article first, then ask what role it plays in the sentence. The object article is why a person says einen Saft, eine Suppe and ein Brötchen. This is the grammar you need before the chapter's ordering tasks.","examples":[["der Apfel → Ich kaufe den Apfel.","the apple → I buy the apple."],["ein Saft → Ich möchte einen Saft.","a juice → I would like a juice."],["eine Suppe → Ich möchte eine Suppe.","a soup → I would like a soup."],["ein Brötchen → Ich nehme ein Brötchen.","a bread roll → I'll take a bread roll."]],"note":"Do not generalise den to every gender. The masculine article changes here; feminine and neuter articles do not.","task":"Complete: Ich kaufe ___ Käse (der Käse).","answer":"den Käse"},{"key":"shop-vowels","title":"Hear umlauts and finish a food exchange","purpose":"Pronounce key foods and use a complete, polite purchase conversation.","text":"Food vocabulary introduces ä, ö and ü. You will hear ä in Käse, ö in Brötchen and ü in Gemüse. The rounded vowel sounds ö and ü are different from plain o and u; listen and repeat rather than guessing their English equivalents. A simple purchase begins with Guten Tag, continues with a request and a price question, then ends with Danke or Auf Wiedersehen. A brief food order is fine here, but full restaurant menus, paying together or separately, and recounting a dinner belong to the later Chapter 6 social situation.","examples":[["Ich möchte zwei Brötchen, bitte.","I would like two rolls, please."],["Was kostet das zusammen?","How much is that altogether?"],["Das macht vier Euro.","That comes to four euros."],["Vielen Dank. Auf Wiedersehen.","Many thanks. Goodbye."]],"note":"Brötchen contains ö; Gemüse contains ü; Käse contains ä. Say the full word with German audio rather than replacing the umlaut.","task":"Say an order for two bread rolls and ask what they cost.","answer":"Ich möchte zwei Brötchen, bitte. Was kostet das?"}]},{"n":5,"title":"Before your Chapter 5 activities","blocks":[{"key":"clocks","title":"Hours, half-hours and schedules","purpose":"Read clock times before describing routines or changing appointments.","text":"In German, um introduces a clock time. Learn that um acht Uhr is at 8:00 and um achtzehn Uhr is at 18:00. Everyday speech uses halb for the coming hour, so halb acht means 7:30, not 8:30. Viertel nach acht is 8:15 and Viertel vor neun is 8:45. A digital timetable might use 15:30, which is read as fünfzehn Uhr dreißig, while conversation might say halb vier. To describe a whole work period, use von neun bis fünfzehn Uhr. Match the expression to an actual clock or schedule before writing a routine.","examples":[["7:30 → halb acht","half past seven"],["8:15 → Viertel nach acht","quarter past eight"],["8:45 → Viertel vor neun","quarter to nine"],["15:30 → fünfzehn Uhr dreißig / halb vier","three thirty p.m."]],"note":"The half-hour points FORWARD: halb neun is 8:30. Am goes with a weekday; um goes with the time.","task":"When does a class start if it starts um halb neun?","answer":"At 08:30."},{"key":"modals","title":"Can, must and want: three modal verbs","purpose":"Understand scheduling conflicts and the sentence bracket.","text":"Use können for can, müssen for must and wollen for want. With a second action, the finite modal comes near the beginning and the other verb stays in the infinitive at the end: Ich kann am Freitag kommen; Ich muss am Samstag arbeiten; Ich will morgen einkaufen. Notice how the forms change: ich kann/muss/will, du kannst/musst/willst, er oder sie kann/muss/will. For questions, move the finite modal to the front: Kannst du am Dienstag kommen? Learn the reason and the alternative day together. This will help you answer appointment questions and understand apologies, not just select a verb from a list.","examples":[["Ich kann heute kommen.","I can come today."],["Ich muss morgen arbeiten.","I must work tomorrow."],["Ich will einkaufen.","I want to shop."],["Kannst du am Freitag kommen?","Can you come on Friday?"]],"note":"Do not conjugate the final action verb after a modal: Ich muss arbeiten, not Ich muss arbeite.","task":"Say 'I want to study German tomorrow' with wollen.","answer":"Ich will morgen Deutsch lernen."},{"key":"phone","title":"Appointments, delays and a clear phone reply","purpose":"Respond politely rather than being tested on unseen appointment language.","text":"An appointment message should clearly state the day, time and response. Ask Haben Sie am Mittwoch um elf Uhr Zeit? If the time does not work, say Leider kann ich nicht, then suggest an alternative. Verspätung means delay or lateness. Mein Bus hat Verspätung tells someone why you cannot arrive on time. In a short phone exchange, state your name, confirm the planned time, explain the problem and propose another time. Pronunciation also matters: German r has different regional realisations, so practise hearing it in arbeiten, Freitag and Termin rather than forcing one English r sound.","examples":[["Haben Sie am Mittwoch um elf Uhr Zeit?","Are you free Wednesday at eleven?"],["Mein Bus hat Verspätung.","My bus is delayed."],["Leider kann ich nicht kommen.","Unfortunately I cannot come."],["Können wir uns um halb vier treffen?","Can we meet at 3:30?"]],"note":"Keep time expressions precise: am Mittwoch (day), um elf Uhr (hour), von neun bis zwölf (range).","task":"Say the bus is delayed and suggest 15:30 instead.","answer":"Mein Bus hat Verspätung. Können wir uns um halb vier treffen?"}]},{"n":6,"title":"Before your Chapter 6 activities","blocks":[{"key":"dates","title":"Write and say calendar dates","purpose":"Understand birthday invitations and announced dates before writing them.","text":"You already know the cardinal numbers. Calendar dates after am usually use ordinal forms: am ersten Mai (1 May), am zweiten Mai, am dritten Mai and am vierten Mai. Notice special forms such as am sechsten, am siebten and am achten. Dates through 19 commonly end in -ten, while dates from 20 onward normally end in -sten: am zwanzigsten Mai and am einundzwanzigsten Mai. In an invitation, write the day, month and time clearly and read all of them aloud. Asking Wann? means when, while Wo? asks for a place. Do not forget the location of the event.","examples":[["am ersten Mai","on 1 May"],["am dritten Mai","on 3 May"],["am zwölften Mai","on 12 May"],["am einundzwanzigsten Mai","on 21 May"]],"note":"An ordinal needs its ending: am drei Mai is not the expected date phrase; am dritten Mai is.","task":"Say 7 May and 20 May as calendar dates.","answer":"am siebten Mai · am zwanzigsten Mai"},{"key":"pronouns","title":"For whom? Direct objects and pronouns","purpose":"Use für + accusative and replace a repeated name in an invitation.","text":"An invitation or gift may be for a person: für dich (for you, informal), für ihn (for him), für sie (for her) or für uns (for us). The preposition für takes the accusative: für den Freund, für einen Freund. You already met accusative articles while shopping in Chapter 4. The same idea helps with personal pronouns: Ich sehe Paul becomes Ich sehe ihn; Ich sehe Anna becomes Ich sehe sie. Other useful forms are mich (me) and dich (you, informal). Name the person first, then choose the object form. This makes a short conversation less repetitive and prepares you for the workbook grammar question.","examples":[["Das ist für dich.","This is for you."],["Das Geschenk ist für meinen Freund.","The gift is for my friend."],["Ich sehe Paul. Ich sehe ihn.","I see Paul. I see him."],["Ich sehe Anna. Ich sehe sie.","I see Anna. I see her."]],"note":"For a masculine direct object use ihn, not er. With für, the masculine article der becomes den.","task":"Complete: Das Geschenk ist ___ dich. Ich sehe Paul. Ich sehe ___.","answer":"für · ihn"},{"key":"sounds","title":"Ei, eu and au in social situations","purpose":"Hear dates, leisure activities and invitations without confusing similar words.","text":"German combines some vowels into one sound. Ei sounds like the English vowel in eye, as in Zeit and drei. Eu and äu share a sound similar to oy, as in Freunde, heute and Häuser. Au resembles ow in house, as in Haus and auch. Practise the whole word, not just the letters. In a short event notice, find the name of the event, date, time, place and possibly ticket price. A friend might write: 'Treffen am Samstag um 18 Uhr im Park. Eintritt frei.' That tells you the day, time, place and that entry is free. Then practise saying whether you can attend.","examples":[["die Zeit · drei","time · three (ei)"],["die Freunde · heute","friends · today (eu)"],["das Haus · auch","house · also (au)"],["Die Feier ist am Samstag.","The celebration is on Saturday."]],"note":"German ei and ie are not interchangeable: drei has the ei diphthong, but sieben has a long ie sound.","task":"Which sound group is in Freunde? Which is in Haus?","answer":"Freunde has eu; Haus has au."}]}];
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const get=n=>chapters.find(c=>c.n===Number(n));
const render=n=>{
const c=get(n);if(!c)return '';
return `<section class="a11-prerequisites" aria-label="Chapter ${c.n} essential language foundations" id="chapter-${c.n}-foundations"><div class="a11-prerequisite-head"><span class="eyebrow">Chapter ${c.n} · Learn this before the chapter challenge</span><h5>${esc(c.title)}</h5><p>Study the complete examples and patterns here before completing the related workbook questions or the final chapter task. The examples are original and follow the uploaded A1.1 chapter objectives.</p></div><nav class="a11-prerequisite-nav" aria-label="Chapter ${c.n} foundational topics">${c.blocks.map((b,i)=>`<button type="button" data-jump-target="ch${c.n}-foundation-${esc(b.key)}">${c.n}.${i+1} ${esc(b.title)} ↓</button>`).join('')}</nav><div class="a11-prerequisite-lessons">${c.blocks.map((b,i)=>`<article class="a11-prerequisite-block" id="ch${c.n}-foundation-${esc(b.key)}"><header><span class="a11-prerequisite-index">${c.n}.${i+1}</span><div><h6>${esc(b.title)}</h6><p>${esc(b.purpose)}</p></div></header><p class="a11-prerequisite-explain">${esc(b.text)}</p><div class="a11-prerequisite-examples">${b.examples.map(([de,en])=>`<div><strong lang="de">${esc(de)}</strong><span>${esc(en)}</span><button type="button" class="view-link" data-speak="${esc(de)}">♫ Listen</button></div>`).join('')}</div><p class="a11-prerequisite-note"><strong>Remember:</strong> ${esc(b.note)}</p><div class="a11-prerequisite-check"><strong>Try it yourself</strong><p>${esc(b.task)}</p><details><summary>Reveal a model answer</summary><p lang="de">${esc(b.answer)}</p></details></div></article>`).join('')}</div></section>`;
};
window.GERMAN_PREREQUISITES={chapters,get,render};
})();
